const kpi=(n,l,s,ico,t="")=>`<article class="kpi"><span class="kpi-icon ${t}">${ico}</span><div><strong>${n}</strong><label>${l}</label><small>${s}</small></div></article>`;
const head=(title,desc,actions="")=>`<div class="heading"><div><div class="eyebrow">GEOTRACIA / ${esc(mod(active)[1])}</div><h1>${title}</h1><p>${desc}</p></div><div class="actions">${actions}</div></div>`;
const panel=(title,body,subtitle="",action="")=>`<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${subtitle?`<div class="sub">${subtitle}</div>`:""}</div>${action}</div>${body}</section>`;
const body=html=>`<div class="panel-body">${html}</div>`;
const activity=(ico,title,desc,time,tone="")=>`<div class="activity"><span class="activity-icon ${tone}">${ico}</span><div><b>${title}</b><p>${desc}</p><small>${time}</small></div></div>`;
const quick=(ico,title,desc,act)=>`<button class="quick" data-action="${act}"><i>${ico}</i><span><b>${title}</b><small>${desc}</small></span></button>`;
const map=()=>`<div class="panel-body"><div class="map"><div class="road"></div><span class="pin p1">✓</span><span class="pin p2">!</span><span class="pin p3">!</span><span class="map-label" style="left:35%;top:48%">Km 12.4</span><span class="map-label" style="left:57%;top:31%">Km 13.8</span><div class="map-tools"><button data-action="layers">▤</button><button data-action="center">⌖</button><button data-action="zoom">+</button></div><div class="legend"><span>Infraestructura</span><span>En revisión</span><span>Incidencia crítica</span></div></div><div class="sub" style="margin-top:9px">Vista territorial esquemática · No representa cartografía georreferenciada.</div></div>`;
function mapPanel(){return panel("Mapa de la red vial",map(),"Capas operativas y referencias de progresiva",btn("Capas","layers"))}
function bars(){let a=[38,28,18,16,9,6],l=["Inspec.","Incid.","Infra.","Interv.","Oper.","Otros"];return panel("Registros por categoría",body(`<div class="bars">${a.map((v,i)=>`<div class="barcol"><b>${v}</b><div class="bar ${i===2||i===3?"green":""}" style="height:${v/40*100}%"></div><small>${l[i]}</small></div>`).join("")}</div><div class="sub" style="margin-top:10px">Distribución demostrativa de registros</div>`),"Resumen de actividad del proyecto")}
function match(r,q){return !q||Object.values(r).some(v=>String(v).toLowerCase().includes(q.toLowerCase()))}
function table(data=records,limit=100){let d=data.slice(0,limit);return `<div class="table-scroll"><table><thead><tr><th>REGISTRO</th><th>TIPO</th><th>CAMINO / KM</th><th>RESPONSABLE</th><th>ESTADO</th><th></th></tr></thead><tbody>${d.map(r=>`<tr><td><span class="cell-title">${esc(r.code)}</span><div class="cell-sub">${esc(r.name)}</div></td><td>${esc(r.type)}</td><td><b>${esc(r.road)}</b><div class="cell-sub">Km ${esc(r.km)}</div></td><td>${esc(r.owner)}</td><td>${badge(r.status,r.tone)}</td><td><div class="row-actions"><button data-view="${esc(r.code)}" title="Ver">◉</button><button data-edit="${esc(r.code)}" title="Editar">✎</button><button data-delete="${esc(r.code)}" title="Eliminar">···</button></div></td></tr>`).join("")||`<tr><td colspan="6"><div class="empty">No hay registros para los filtros seleccionados.</div></td></tr>`}</tbody></table></div>`}
function tableTools(){return `<div class="table-tools"><label class="field-search">⌕ <input id="tableSearch" placeholder="Buscar código, descripción, responsable…" value="${esc(query)}"></label><select class="field" id="typeFilter" style="max-width:160px"><option value="">Todos los tipos</option>${["Inspección","Incidencia","Infraestructura","Intervención","Operación"].map(x=>`<option ${typeFilter===x?"selected":""}>${x}</option>`).join("")}</select><button class="btn" data-action="clear-filters">Limpiar filtros</button></div>`}
function recordPanel(){let d=records.filter(r=>match(r,query)&&(!typeFilter||r.type===typeFilter));return panel("Registros del módulo",`${tableTools()}<div id="recordsTable">${table(d)}</div><div class="pagination"><span>${d.length} registros visibles · almacenamiento local</span><div class="pages"><button>‹</button><button class="selected">1</button><button>›</button></div></div>`,"Consulta, filtra y abre los registros para revisar sus datos.",btn("＋ Nuevo registro","new-record","primary"))}
function dash(){return `${head("Control territorial","Una visión clara del estado de la red, las actividades de terreno y los asuntos que requieren atención.",btn("↓ Exportar resumen","export-csv")+btn("＋ Nuevo registro","new-record","primary"))}<div class="kpis">${kpi("156","Registros incluidos","En el proyecto","▤")}${kpi("42,6 km","Red analizada","Tramos seleccionados","⌁","teal")}${kpi("28","Incidencias","4 requieren atención","△","amber")}${kpi("16","Intervenciones","Mantenimiento","⚒","purple")}${kpi("94,2%","Cobertura de inspección","Periodo actual","✓","teal")}${kpi("3","Pendientes críticos","Revisión requerida","!","red")}</div><div class="grid2">${mapPanel()}${panel("Actividad reciente",body(`<div>${activity("☑","Inspección de pavimento","INS-2026-028 · Ruta R-720, km 12+300","Hoy · 14:32","teal")}${activity("△","Desprendimiento de talud","INC-2026-067 · Requiere evaluación","Hoy · 12:18","red")}${activity("▤","Activo vial actualizado","INF-2026-012 · Alcantarilla","Ayer · 16:20")}${activity("⚒","Mantenimiento programado","MAN-2026-015 · Bacheo","Ayer · 11:45","amber")}</div>${btn("Ver toda la actividad","go-reports")}`),"Últimos movimientos del proyecto")}</div><div class="grid3">${bars()}${recordPanel()}${panel("Acciones frecuentes",body(`<div class="quick-grid">${quick("＋","Crear registro","Formulario técnico","new-record")}${quick("△","Reportar incidencia","Evento en terreno","new-incident")}${quick("▥","Generar informe","Resumen de la red","go-reports")}${quick("♙","Gestionar usuarios","Accesos del equipo","go-users")}${quick("☁","Preparar offline","Mapas y registros","go-offline")}${quick("⚙","Configuración","Preferencias del proyecto","go-config")}</div>`))}</div>`}
function recordsModule(){let d=records.filter(r=>match(r,query));if(active==="inspecciones")d=d.filter(r=>r.type==="Inspección");if(active==="incidencias")d=d.filter(r=>r.type==="Incidencia");if(active==="mantenimiento")d=d.filter(r=>r.type==="Intervención");if(active==="inventario")d=d.filter(r=>r.type==="Infraestructura");if(active==="operaciones")d=d.filter(r=>r.type==="Operación");return `${head(mod(active)[1],mod(active)[3],btn("↓ Exportar","export-csv")+btn("＋ Nuevo registro",active==="incidencias"?"new-incident":"new-record","primary"))}<div class="kpis">${kpi(d.length,"Registros visibles","Según filtros","▤")}${kpi(d.filter(r=>r.tone==="danger").length,"Prioridad crítica","Revisión requerida","△","red")}${kpi(d.filter(r=>r.tone==="warning").length,"Pendientes","En seguimiento","◷","amber")}${kpi("R-720","Camino activo","Proyecto seleccionado","⌁","teal")}${kpi("42,6 km","Extensión","Red de referencia","↗","purple")}${kpi("20 oct","Última actividad","Fecha de ejemplo","▦")}</div>${recordPanel()}<div class="module-layout" style="margin-top:15px"><div>${mapPanel()}</div><div>${panel("Seguimiento",body(`<div class="progress-row"><span>Completados</span><b>68%</b></div><div class="progress"><span style="width:68%"></span></div><div class="settings-row"><span class="setting-icon">✓</span><span class="setting-copy"><b>Completados</b><small>Actividades cerradas o verificadas</small></span></div><div class="settings-row"><span class="setting-icon">◷</span><span class="setting-copy"><b>Pendientes de revisión</b><small>Requieren acción del equipo</small></span></div>`))}</div></div>`}
function settingsRow(ico,title,desc,status=""){return `<div class="settings-row"><span class="setting-icon">${ico}</span><span class="setting-copy"><b>${title}</b><small>${desc}</small></span>${status?badge(status,status==="Activo"?"success":"warning"):""}</div>`}
function projectModule(){
 const client=window.geoSupabase;
 if(!client) return `${head("Proyectos","Administra el ciclo de vida de los proyectos territoriales.")}<div class="note">Inicia sesión para consultar los proyectos.</div>`;
 if(geoProjectsLoading) return `${head("Proyectos","Portafolio territorial de tu organización.")}<section class="panel"><div class="panel-body">Consultando proyectos en Supabase…</div></section>`;
 if(geoProjectsError) return `${head("Proyectos","Portafolio territorial de tu organización.",btn("↻ Reintentar","reload-projects","primary"))}<div class="note">${esc(geoProjectsError)}</div>`;
 if(!geoOrg) return `${head("Configurar espacio de trabajo","Crea la organización propietaria de los proyectos y sus datos.")}<section class="panel"><div class="panel-head"><div><h2>Crear organización</h2><div class="sub">Los datos quedan aislados por organización mediante políticas RLS.</div></div></div><div class="panel-body"><form id="orgCreateForm" class="form-grid"><div class="full"><label class="field-label" for="orgCreateName">Nombre de la organización</label><input class="field" id="orgCreateName" required minlength="2" maxlength="160" placeholder="Ej. Consultora Vial Sur"></div><div class="full"><button class="btn primary" type="submit">Crear espacio de trabajo</button></div></form></div></section>`;
 const q=(document.querySelector('#projectSearch')?.value||'').trim().toLowerCase();
 const statusFilter=document.querySelector('#projectStatusFilter')?.value||'';
 const typeFilterProject=document.querySelector('#projectTypeFilter')?.value||'';
 const filtered=geoProjects.filter(p=>{const hay=[p.name,p.code,p.description,p.region,p.municipality,p.client_name,p.manager_name,p.project_type,p.address].join(' ').toLowerCase();return (!q||hay.includes(q))&&(!statusFilter||p.status===statusFilter)&&(!typeFilterProject||p.project_type===typeFilterProject)});
 const rows=filtered.map(p=>`<tr><td><span class="cell-title">${esc(p.code||'Sin código')}</span><div class="cell-sub">${esc(p.project_type||'Proyecto territorial')} · ${esc(p.priority||'Prioridad normal')}</div></td><td><b>${esc(p.name)}</b><div class="cell-sub">${esc(p.client_name||'Sin mandante')}</div></td><td>${esc([p.municipality,p.region].filter(Boolean).join(', ')||'Sin ubicación')}</td><td>${badge(projectStatus(p.status),['closed','archived'].includes(p.status)?'warning':p.status==='in_progress'?'info':'success')}</td><td>${p.start_date?new Date(p.start_date+'T12:00:00').toLocaleDateString('es-CL'):'—'}<div class="cell-sub">Término: ${p.due_date?new Date(p.due_date+'T12:00:00').toLocaleDateString('es-CL'):'sin fecha'}</div></td><td>${p.budget!=null?new Intl.NumberFormat('es-CL',{style:'currency',currency:p.currency||'CLP',maximumFractionDigits:0}).format(Number(p.budget)):'—'}</td><td><div class="row-actions"><button type="button" data-project-view="${esc(p.id)}" title="Ver ficha">◉</button><button type="button" data-project-edit="${esc(p.id)}" title="Editar">✎</button><button type="button" data-project-delete="${esc(p.id)}" title="Archivar">▣</button></div></td></tr>`).join('');
 const budget=geoProjects.filter(p=>p.budget!=null&&!['archived'].includes(p.status)).reduce((n,p)=>n+Number(p.budget||0),0);
 return `${head("Gestión de proyectos",`Portafolio de <b>${esc(geoOrg.name)}</b>. Administración de alcance, responsables, plazos, presupuesto y ubicación.`,btn("↓ Exportar CSV","export-projects")+btn("↻ Actualizar","reload-projects")+btn("＋ Nuevo proyecto","new-project","primary"))}
 <div class="kpis">${kpi(geoProjects.length,'Proyectos registrados','Portafolio de la organización','▦')}${kpi(geoProjects.filter(p=>['open','in_progress'].includes(p.status)).length,'Activos','Abiertos o en ejecución','✓','teal')}${kpi(geoProjects.filter(p=>p.status==='in_progress').length,'En ejecución','Trabajo en curso','↻','amber')}${kpi(geoProjects.filter(p=>p.status==='closed').length,'Finalizados','Cierre registrado','▤','purple')}${kpi(new Intl.NumberFormat('es-CL',{style:'currency',currency:'CLP',maximumFractionDigits:0}).format(budget),'Presupuesto total','Suma referencial en CLP','＄','teal')}</div>
 <section class="panel"><div class="panel-head"><div><h2>Directorio de proyectos</h2><div class="sub">Datos persistidos en PostgreSQL · ${filtered.length} de ${geoProjects.length} proyectos</div></div></div><div class="panel-body"><div class="table-tools project-tools"><label class="field-search">⌕ <input id="projectSearch" placeholder="Buscar nombre, código, mandante o ubicación…" value="${esc(q)}"></label><select class="field" id="projectStatusFilter"><option value="">Todos los estados</option>${[['draft','Borrador'],['open','Activo'],['in_progress','En ejecución'],['resolved','Resuelto'],['closed','Cerrado'],['archived','Archivado']].map(([v,l])=>`<option value="${v}" ${statusFilter===v?'selected':''}>${l}</option>`).join('')}</select><select class="field" id="projectTypeFilter"><option value="">Todos los tipos</option>${[...new Set(geoProjects.map(p=>p.project_type).filter(Boolean))].sort().map(t=>`<option value="${esc(t)}" ${typeFilterProject===t?'selected':''}>${esc(t)}</option>`).join('')}</select><button class="btn" data-action="clear-project-filters">Limpiar</button></div><div class="table-scroll"><table><thead><tr><th>CÓDIGO / TIPO</th><th>PROYECTO / MANDANTE</th><th>UBICACIÓN</th><th>ESTADO</th><th>PLAZO</th><th>PRESUPUESTO</th><th>ACCIONES</th></tr></thead><tbody>${rows||'<tr><td colspan="7"><div class="empty">No hay proyectos que coincidan con los filtros. Crea un proyecto o ajusta la búsqueda.</div></td></tr>'}</tbody></table></div></div></section>
 <div class="note" style="margin-top:12px">La organización y sus permisos se validan en Supabase mediante RLS. El archivado conserva el historial y no elimina los registros asociados.</div>`;
}
function projectStatus(s){return ({draft:'Borrador',open:'Activo',in_progress:'En ejecución',resolved:'Resuelto',closed:'Cerrado',archived:'Archivado'})[s]||s||'Activo'}
async function loadGeoProjects(){const client=window.geoSupabase;if(!client)return;geoProjectsLoading=true;geoProjectsError='';if(active==='proyectos')show();try{const {data:userData,error:userError}=await client.auth.getUser();if(userError)throw userError;geoCurrentUser=userData.user;if(!geoCurrentUser)throw new Error('La sesión no está activa. Inicia sesión nuevamente.');const {data:members,error:mErr}=await client.from('members').select('organization_id, role, organizations(id,name)').eq('user_id',geoCurrentUser.id).eq('active',true).limit(1);if(mErr)throw mErr;const membership=members?.[0];if(!membership){geoOrg=null;geoProjects=[];return;}geoOrg={id:membership.organization_id,name:membership.organizations?.name||'Organización',role:membership.role};const {data,error}=await client.from('projects').select('id,organization_id,name,code,description,region,status,created_by,created_at,updated_at,project_type,priority,client_name,manager_name,municipality,address,start_date,due_date,budget,currency,latitude,longitude,objectives').eq('organization_id',geoOrg.id).order('created_at',{ascending:false});if(error)throw error;geoProjects=data||[];}catch(e){geoProjectsError=projectErrorMessage(e);geoProjects=[];}finally{geoProjectsLoading=false;if(active==='proyectos')show();if(active==='inventario'&&!inventoryLoading)loadInventoryData(inventoryProjectId);}}
function projectErrorMessage(e){const m=e?.message||'No fue posible consultar los proyectos.';if(/relation .* does not exist|schema cache|column .* does not exist/i.test(m))return 'Falta aplicar la migración del módulo de proyectos territoriales en Supabase. Ejecuta el archivo SQL incluido en el paquete y vuelve a intentar.';if(/permission denied|row-level security|violates row-level/i.test(m))return 'Supabase rechazó la operación por permisos o políticas RLS. Verifica tu pertenencia y rol en la organización.';return m}
function newProject(p=null){const v=(key,def='')=>p?.[key]??def;dialog(p?'Editar proyecto':'Nuevo proyecto',`<form id="projectForm" class="form-grid">
 <div class="full"><label class="field-label" for="pName">Nombre del proyecto *</label><input class="field" id="pName" required minlength="3" maxlength="160" value="${esc(v('name'))}" placeholder="Ej. Conservación Ruta R-720"></div>
 <div><label class="field-label" for="pCode">Código interno</label><input class="field" id="pCode" maxlength="60" value="${esc(v('code'))}" placeholder="Ej. GT-2026-001"></div><div><label class="field-label" for="pType">Tipo de proyecto</label><select class="field" id="pType">${['Infraestructura vial','Conservación vial','Inspección territorial','Obra pública','Planificación urbana','Gestión de activos','Estudio territorial','Otro'].map(x=>`<option ${v('project_type','Infraestructura vial')===x?'selected':''}>${x}</option>`).join('')}</select></div>
 <div><label class="field-label" for="pStatus">Estado *</label><select class="field" id="pStatus">${[['draft','Borrador'],['open','Activo'],['in_progress','En ejecución'],['resolved','Resuelto'],['closed','Cerrado'],['archived','Archivado']].map(([x,l])=>`<option value="${x}" ${v('status','open')===x?'selected':''}>${l}</option>`).join('')}</select></div><div><label class="field-label" for="pPriority">Prioridad</label><select class="field" id="pPriority">${[['low','Baja'],['normal','Normal'],['high','Alta'],['critical','Crítica']].map(([x,l])=>`<option value="${x}" ${v('priority','normal')===x?'selected':''}>${l}</option>`).join('')}</select></div>
 <div><label class="field-label" for="pClient">Mandante / cliente</label><input class="field" id="pClient" maxlength="180" value="${esc(v('client_name'))}" placeholder="Municipalidad, MOP, empresa…"></div><div><label class="field-label" for="pManager">Responsable del proyecto</label><input class="field" id="pManager" maxlength="180" value="${esc(v('manager_name'))}" placeholder="Nombre del responsable"></div>
 <div><label class="field-label" for="pRegion">Región</label><input class="field" id="pRegion" maxlength="120" value="${esc(v('region'))}" placeholder="La Araucanía"></div><div><label class="field-label" for="pMunicipality">Comuna</label><input class="field" id="pMunicipality" maxlength="120" value="${esc(v('municipality'))}" placeholder="Temuco"></div>
 <div class="full"><label class="field-label" for="pAddress">Ubicación / dirección / área</label><input class="field" id="pAddress" maxlength="300" value="${esc(v('address'))}" placeholder="Sector, ruta, comuna o referencia territorial"></div>
 <div><label class="field-label" for="pLatitude">Latitud (WGS 84)</label><input class="field" id="pLatitude" type="number" min="-56" max="-17" step="any" value="${esc(v('latitude'))}" placeholder="-38.7359"></div><div><label class="field-label" for="pLongitude">Longitud (WGS 84)</label><input class="field" id="pLongitude" type="number" min="-76" max="-66" step="any" value="${esc(v('longitude'))}" placeholder="-72.5904"></div>
 <div><label class="field-label" for="pStart">Fecha de inicio</label><input class="field" id="pStart" type="date" value="${esc(v('start_date'))}"></div><div><label class="field-label" for="pDue">Fecha de término planificada</label><input class="field" id="pDue" type="date" value="${esc(v('due_date'))}"></div>
 <div><label class="field-label" for="pBudget">Presupuesto referencial</label><input class="field" id="pBudget" type="number" min="0" step="1" value="${esc(v('budget'))}" placeholder="0"></div><div><label class="field-label" for="pCurrency">Moneda</label><select class="field" id="pCurrency">${['CLP','UF','USD'].map(x=>`<option ${v('currency','CLP')===x?'selected':''}>${x}</option>`).join('')}</select></div>
 <div class="full"><label class="field-label" for="pObjectives">Objetivos y alcance</label><textarea class="field" id="pObjectives" rows="3" maxlength="4000" placeholder="Objetivo general, entregables y alcance territorial">${esc(v('objectives'))}</textarea></div><div class="full"><label class="field-label" for="pDescription">Descripción / observaciones</label><textarea class="field" id="pDescription" rows="3" maxlength="4000" placeholder="Antecedentes, alcance técnico y notas">${esc(v('description'))}</textarea></div>
 <div class="note full">Las coordenadas son opcionales y corresponden a WGS 84. Las fechas y el presupuesto son datos de planificación; no representan pagos ejecutados.</div></form>`,`<button class="btn" data-close>Cancelar</button><button class="btn primary" data-action="save-project" data-project-id="${esc(p?.id||'')}">Guardar proyecto</button>`)}
async function saveGeoProject(id=''){const form=$('#projectForm');if(!form?.reportValidity())return;if(!geoOrg)return toast('Primero crea o selecciona una organización.');const startDate=$('#pStart').value||null,dueDate=$('#pDue').value||null;if(startDate&&dueDate&&dueDate<startDate)return toast('La fecha de término no puede ser anterior a la fecha de inicio.');const lat=$('#pLatitude').value.trim(),lon=$('#pLongitude').value.trim();if((lat&&!lon)||(!lat&&lon))return toast('Ingresa latitud y longitud juntas.');const payload={organization_id:geoOrg.id,name:$('#pName').value.trim(),code:$('#pCode').value.trim()||null,region:$('#pRegion').value.trim()||null,description:$('#pDescription').value.trim(),status:$('#pStatus').value,project_type:$('#pType').value,priority:$('#pPriority').value,client_name:$('#pClient').value.trim()||null,manager_name:$('#pManager').value.trim()||null,municipality:$('#pMunicipality').value.trim()||null,address:$('#pAddress').value.trim()||null,start_date:startDate,due_date:dueDate,budget:$('#pBudget').value===''?null:Number($('#pBudget').value),currency:$('#pCurrency').value,latitude:lat?Number(lat):null,longitude:lon?Number(lon):null,objectives:$('#pObjectives').value.trim()||null,updated_at:new Date().toISOString(),created_by:geoCurrentUser?.id};const button=$('[data-action=save-project]');if(button){button.disabled=true;button.textContent='Guardando…'}try{let result;if(id){delete payload.created_by;result=await window.geoSupabase.from('projects').update(payload).eq('id',id).eq('organization_id',geoOrg.id).select('id').single()}else result=await window.geoSupabase.from('projects').insert(payload).select('id').single();if(result.error)throw result.error;try{await window.geoSupabase.from('audit_logs').insert({organization_id:geoOrg.id,actor_id:geoCurrentUser?.id,action:id?'project.updated':'project.created',entity_table:'projects',entity_id:result.data.id,details:{name:payload.name,code:payload.code,status:payload.status,project_type:payload.project_type}})}catch{}$('#dialog').close();toast(id?'Proyecto actualizado en Supabase':'Proyecto creado en Supabase');await loadGeoProjects()}catch(e){toast(projectErrorMessage(e))}finally{if(button){button.disabled=false;button.textContent='Guardar proyecto'}}}
async function createGeoOrganization(name){const client=window.geoSupabase;try{const {data,error}=await client.rpc('create_my_organization',{org_name:name.trim()});if(error)throw error;toast('Organización creada');await loadGeoProjects()}catch(e){toast(projectErrorMessage(e))}}
function viewGeoProject(id){const p=geoProjects.find(x=>x.id===id);if(!p)return;const money=p.budget==null?'No definido':new Intl.NumberFormat('es-CL',{style:'currency',currency:p.currency||'CLP',maximumFractionDigits:0}).format(Number(p.budget));const coord=p.latitude!=null&&p.longitude!=null?`${p.latitude}, ${p.longitude}`:'No definidas';const fields=[['Código',p.code||'—'],['Tipo',p.project_type||'—'],['Estado',projectStatus(p.status)],['Prioridad',({low:'Baja',normal:'Normal',high:'Alta',critical:'Crítica'})[p.priority]||'Normal'],['Mandante',p.client_name||'—'],['Responsable',p.manager_name||'—'],['Región',p.region||'—'],['Comuna',p.municipality||'—'],['Ubicación',p.address||'—'],['Coordenadas WGS 84',coord],['Inicio',p.start_date||'—'],['Término planificado',p.due_date||'—'],['Presupuesto',money],['Creado',p.created_at?new Date(p.created_at).toLocaleString('es-CL'):'—'],['Última actualización',p.updated_at?new Date(p.updated_at).toLocaleString('es-CL'):'—']];dialog('Ficha del proyecto',`<div class="project-detail"><h3>${esc(p.name)}</h3><p>${esc(p.description||'Sin descripción adicional')}</p><div class="form-grid">${fields.map(([l,v])=>`<div><label class="field-label">${esc(l)}</label><div>${esc(v)}</div></div>`).join('')}<div class="full"><label class="field-label">Objetivos y alcance</label><p>${esc(p.objectives||'No definidos')}</p></div></div>${p.latitude!=null&&p.longitude!=null?`<p><a href="https://www.openstreetmap.org/?mlat=${encodeURIComponent(p.latitude)}&mlon=${encodeURIComponent(p.longitude)}#map=15/${encodeURIComponent(p.latitude)}/${encodeURIComponent(p.longitude)}" target="_blank" rel="noopener">Abrir ubicación en OpenStreetMap ↗</a></p>`:''}</div>`,`<button class="btn" data-close>Cerrar</button><button class="btn" data-action="project-roads-open" data-project-id="${esc(p.id)}">Caminos y tramos</button><button class="btn primary" data-action="edit-project-from-view" data-project-id="${esc(p.id)}">Editar proyecto</button>`)}
async function openProjectRoads(projectId){
 const p=geoProjects.find(x=>x.id===projectId);if(!p||!geoOrg)return;
 try{
  const [a,b]=await Promise.all([
   window.geoSupabase.from('roads').select('id,code,name,road_type,surface_type,length_m').eq('organization_id',geoOrg.id).eq('project_id',p.id).order('name'),
   window.geoSupabase.from('segments').select('id,road_id,code,start_km,end_km,condition').eq('organization_id',geoOrg.id).eq('project_id',p.id).order('start_km')
  ]);
  if(a.error)throw a.error;if(b.error)throw b.error;
  const roads=a.data||[],segments=b.data||[];
  const rrows=roads.map(r=>'<tr><td>'+esc(r.code)+'</td><td>'+esc(r.name)+'</td><td>'+esc(r.road_type||'Ruta')+'</td><td>'+(r.length_m==null?'—':(Number(r.length_m)/1000).toLocaleString('es-CL',{maximumFractionDigits:2})+' km')+'</td><td>'+segments.filter(s=>s.road_id===r.id).length+'</td></tr>').join('');
  const srows=segments.map(x=>'<tr><td>'+esc(x.code)+'</td><td>'+esc(roads.find(r=>r.id===x.road_id)?.name||'Camino')+'</td><td>'+Number(x.start_km).toLocaleString('es-CL')+' – '+Number(x.end_km).toLocaleString('es-CL')+' km</td><td>'+esc(x.condition||'Sin evaluar')+'</td></tr>').join('');
  const html='<div class="kpis">'+kpi(roads.length,'Caminos asociados','Proyecto actual','⌁')+kpi(segments.length,'Tramos registrados','Progresivas en km','↗')+'</div><div class="panel" style="margin-top:12px"><div class="panel-head"><div><h2>Caminos</h2><div class="sub">Catastro del proyecto</div></div><button class="btn primary" data-action="project-road-new" data-project-id="'+esc(p.id)+'">＋ Nuevo camino</button></div><div class="panel-body"><div class="table-scroll"><table><thead><tr><th>CÓDIGO</th><th>NOMBRE</th><th>TIPO</th><th>LONGITUD</th><th>TRAMOS</th></tr></thead><tbody>'+(rrows||'<tr><td colspan="5">No hay caminos asociados todavía.</td></tr>')+'</tbody></table></div></div></div><div class="panel" style="margin-top:12px"><div class="panel-head"><div><h2>Tramos</h2><div class="sub">Progresivas de inicio y término</div></div><button class="btn primary" data-action="project-segment-new" data-project-id="'+esc(p.id)+'" '+(!roads.length?'disabled':'')+'>＋ Nuevo tramo</button></div><div class="panel-body"><div class="table-scroll"><table><thead><tr><th>CÓDIGO</th><th>CAMINO</th><th>PROGRESIVA</th><th>CONDICIÓN</th></tr></thead><tbody>'+(srows||'<tr><td colspan="4">No hay tramos asociados todavía.</td></tr>')+'</tbody></table></div></div></div><div class="note" style="margin-top:12px">La longitud declarada no se confunde con la longitud calculada desde geometría.</div>';
  dialog('Caminos y tramos · '+p.name,html,'<button class="btn" data-close>Cerrar</button>');
 }catch(err){dialog('Caminos y tramos','<div class="note">'+esc(projectErrorMessage(err))+'</div><p>Confirma que la migración de caminos y tramos está aplicada en Supabase y que tu usuario tiene permisos en la organización.</p>','<button class="btn" data-close>Cerrar</button>')}
}
function newProjectRoad(projectId){
 const p=geoProjects.find(x=>x.id===projectId);if(!p||!geoOrg)return;
 dialog('Nuevo camino asociado al proyecto','<form id="projectRoadForm" class="form-grid"><div><label class="field-label">Código *</label><input class="field" id="prCode" required maxlength="60" placeholder="Ej. R-720"></div><div><label class="field-label">Nombre *</label><input class="field" id="prName" required maxlength="180" placeholder="Nombre del camino"></div><div><label class="field-label">Tipo</label><select class="field" id="prType"><option>Ruta</option><option>Camino rural</option><option>Calle urbana</option><option>Acceso</option><option>Sendero</option><option>Otro</option></select></div><div><label class="field-label">Superficie</label><select class="field" id="prSurface"><option>Sin especificar</option><option>Asfalto</option><option>Hormigón</option><option>Ripio</option><option>Tierra</option><option>Mixta</option></select></div><div class="full"><label class="field-label">Longitud declarada (metros, opcional)</label><input class="field" id="prLength" type="number" min="0" step="0.01" placeholder="Ej. 12500"></div></form>','<button class="btn" data-close>Cancelar</button><button class="btn primary" data-action="project-road-save" data-project-id="'+esc(p.id)+'">Guardar camino</button>');
}
async function saveProjectRoad(projectId){
 const f=$('#projectRoadForm');if(!f?.reportValidity()||!geoOrg)return;
 const payload={organization_id:geoOrg.id,project_id:projectId,code:$('#prCode').value.trim(),name:$('#prName').value.trim(),road_type:$('#prType').value,surface_type:$('#prSurface').value,length_m:$('#prLength').value===''?null:Number($('#prLength').value),created_by:geoCurrentUser?.id||null};
 try{const {error}=await window.geoSupabase.from('roads').insert(payload);if(error)throw error;toast('Camino guardado en Supabase');await openProjectRoads(projectId)}catch(err){toast(projectErrorMessage(err))}
}
async function newProjectSegment(projectId){
 const p=geoProjects.find(x=>x.id===projectId);if(!p||!geoOrg)return;
 try{
  const {data,error}=await window.geoSupabase.from('roads').select('id,code,name').eq('organization_id',geoOrg.id).eq('project_id',projectId).order('name');if(error)throw error;
  const roads=data||[];if(!roads.length)return toast('Primero registra un camino en este proyecto.');
  dialog('Nuevo tramo asociado','<form id="projectSegmentForm" class="form-grid"><div class="full"><label class="field-label">Camino *</label><select class="field" id="psRoad" required>'+roads.map(x=>'<option value="'+esc(x.id)+'">'+esc(x.code+' · '+x.name)+'</option>').join('')+'</select></div><div><label class="field-label">Código del tramo *</label><input class="field" id="psCode" required maxlength="60" placeholder="Ej. R720-TR-001"></div><div><label class="field-label">Condición</label><select class="field" id="psCondition"><option>Sin evaluar</option><option>Bueno</option><option>Regular</option><option>Malo</option></select></div><div><label class="field-label">Progresiva inicial (km) *</label><input class="field" id="psStart" type="number" required min="0" step="0.001" placeholder="0.000"></div><div><label class="field-label">Progresiva final (km) *</label><input class="field" id="psEnd" type="number" required min="0.001" step="0.001" placeholder="1.000"></div><div class="note full">La progresiva final debe ser mayor que la inicial.</div></form>','<button class="btn" data-close>Cancelar</button><button class="btn primary" data-action="project-segment-save" data-project-id="'+esc(p.id)+'">Guardar tramo</button>');
 }catch(err){toast(projectErrorMessage(err))}
}
async function saveProjectSegment(projectId){
 const f=$('#projectSegmentForm');if(!f?.reportValidity()||!geoOrg)return;
 const start=Number($('#psStart').value),end=Number($('#psEnd').value);if(!(end>start))return toast('La progresiva final debe ser mayor que la inicial.');
 const payload={organization_id:geoOrg.id,project_id:projectId,road_id:$('#psRoad').value,code:$('#psCode').value.trim(),start_km:start,end_km:end,condition:$('#psCondition').value,created_by:geoCurrentUser?.id||null};
 try{const {error}=await window.geoSupabase.from('segments').insert(payload);if(error)throw error;toast('Tramo guardado en Supabase');await openProjectRoads(projectId)}catch(err){toast(projectErrorMessage(err))}
}

function exportGeoProjects(){const cols=['code','name','project_type','status','priority','client_name','manager_name','region','municipality','address','latitude','longitude','start_date','due_date','budget','currency','objectives','description','created_at','updated_at'];const labels=['Código','Nombre','Tipo','Estado','Prioridad','Mandante','Responsable','Región','Comuna','Ubicación','Latitud','Longitud','Inicio','Término','Presupuesto','Moneda','Objetivos','Descripción','Creado','Actualizado'];const csv=[labels,...geoProjects.map(p=>cols.map(k=>p[k]??''))].map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\n');exportFile('geotracia-proyectos.csv',csv,'text/csv;charset=utf-8');toast('Directorio de proyectos exportado a CSV')}
async function archiveGeoProject(id){const p=geoProjects.find(x=>x.id===id);if(!p)return;dialog('Archivar proyecto',`<p>¿Archivar <b>${esc(p.name)}</b>?</p><div class="note">El proyecto se conservará junto con su historial. Podrás seguir consultándolo al filtrar por estado archivado.</div>`,`<button class="btn" data-close>Cancelar</button><button class="btn primary" data-action="archive-project-confirm" data-project-id="${esc(id)}">Archivar</button>`)}
async function confirmArchiveProject(id){try{const {error}=await window.geoSupabase.from('projects').update({status:'archived',updated_at:new Date().toISOString()}).eq('id',id).eq('organization_id',geoOrg.id);if(error)throw error;try{await window.geoSupabase.from('audit_logs').insert({organization_id:geoOrg.id,actor_id:geoCurrentUser?.id,action:'project.archived',entity_table:'projects',entity_id:id,details:{name:geoProjects.find(p=>p.id===id)?.name}})}catch{}$('#dialog').close();toast('Proyecto archivado');await loadGeoProjects()}catch(e){toast(projectErrorMessage(e))}}
function kilometrajeModule(){
 const projects=geoProjects.filter(p=>p.status!=='archived');
 const selected=projects.find(p=>p.id===kmProjectId)||projects[0];
 if(selected&&!kmProjectId)kmProjectId=selected.id;
 const options=projects.map(p=>`<option value="${esc(p.id)}" ${p.id===kmProjectId?'selected':''}>${esc((p.code?p.code+' · ':'')+p.name)}</option>`).join('');
 const roadsRows=kmRoads.map(r=>{const segs=kmSegments.filter(s=>s.road_id===r.id);const km=Number(r.length_m||r.official_length_m||r.geometry_length_m||0)/1000;return `<tr><td><b>${esc(r.code)}</b></td><td>${esc(r.name)}</td><td>${esc(r.road_type||'Ruta')}</td><td>${km?km.toLocaleString('es-CL',{maximumFractionDigits:3})+' km':'—'}</td><td>${segs.length}</td><td>${segs.length?segs.map(s=>`${Number(s.start_km).toLocaleString('es-CL',{maximumFractionDigits:3})}–${Number(s.end_km).toLocaleString('es-CL',{maximumFractionDigits:3})} km`).join('<br>'):'<span class="sub">Sin tramos</span>'}</td></tr>`}).join('');
 const segRows=kmSegments.map(s=>{const r=kmRoads.find(x=>x.id===s.road_id);return `<tr><td>${esc(s.code)}</td><td>${esc(r?.code||'—')} · ${esc(r?.name||'Camino')}</td><td>${Number(s.start_km).toLocaleString('es-CL',{minimumFractionDigits:3,maximumFractionDigits:3})}</td><td>${Number(s.end_km).toLocaleString('es-CL',{minimumFractionDigits:3,maximumFractionDigits:3})}</td><td>${(Number(s.end_km)-Number(s.start_km)).toLocaleString('es-CL',{minimumFractionDigits:3,maximumFractionDigits:3})} km</td><td>${badge(s.condition||'Sin evaluar',s.condition==='Bueno'?'success':s.condition==='Malo'?'danger':s.condition==='Regular'?'warning':'')}</td></tr>`}).join('');
 return `${head('Kilometraje y progresiva','Consulta técnica de caminos y tramos persistidos en Supabase. Las progresivas se expresan en kilómetros y se mantienen asociadas al camino.',btn('↻ Actualizar','kilometraje-reload'))}
 <section class="panel"><div class="panel-head"><div><h2>Proyecto de trabajo</h2><div class="sub">Selecciona el proyecto para consultar sus caminos y progresivas reales.</div></div></div><div class="panel-body"><label class="field-label" for="kmProjectSelect">Proyecto</label><select class="field" id="kmProjectSelect" ${!projects.length?'disabled':''}><option value="">Seleccionar proyecto…</option>${options}</select>${geoProjectsLoading?'<p class="sub">Cargando proyectos…</p>':''}${geoProjectsError?`<div class="note">${esc(geoProjectsError)}</div>`:''}${!window.geoSupabase?'<div class="note">Supabase no está configurado; no se mostrarán datos simulados como si fueran reales.</div>':''}${kmError?`<div class="note">${esc(kmError)}</div>`:''}</div></section>
 ${kmLoading?'<section class="panel"><div class="panel-body">Consultando caminos y tramos…</div></section>':`<div class="kpis">${kpi(kmRoads.length,'Caminos','Proyecto seleccionado','⌁')}${kpi(kmSegments.length,'Tramos','Registros persistidos','↗','teal')}${kpi(kmSegments.filter(s=>s.condition==='Malo').length,'Tramos en mal estado','Requieren revisión','△','red')}${kpi(kmSegments.filter(s=>s.condition==='Sin evaluar'||!s.condition).length,'Sin evaluar','Pendiente de inspección','◷','amber')}</div>
 <section class="panel"><div class="panel-head"><div><h2>Progresivas por camino</h2><div class="sub">Longitud y rangos de los tramos registrados</div></div></div><div class="panel-body"><div class="table-scroll"><table><thead><tr><th>CÓDIGO</th><th>CAMINO</th><th>TIPO</th><th>LONGITUD</th><th>TRAMOS</th><th>RANGOS DE PROGRESIVA</th></tr></thead><tbody>${roadsRows||`<tr><td colspan="6">${selected?'No hay caminos registrados para este proyecto.':'Selecciona un proyecto para consultar sus caminos.'}</td></tr>`}</tbody></table></div></div></section>
 <section class="panel" style="margin-top:14px"><div class="panel-head"><div><h2>Detalle de tramos</h2><div class="sub">Progresiva inicial y final, longitud calculada y condición</div></div></div><div class="panel-body"><div class="table-scroll"><table><thead><tr><th>CÓDIGO TRAMO</th><th>CAMINO</th><th>INICIO (KM)</th><th>TÉRMINO (KM)</th><th>LONGITUD</th><th>CONDICIÓN</th></tr></thead><tbody>${segRows||'<tr><td colspan="6">No hay tramos registrados para el proyecto seleccionado.</td></tr>'}</tbody></table></div><p class="sub" style="margin-top:10px">La longitud de un tramo se calcula como progresiva final menos inicial. No reemplaza la longitud geométrica ni la longitud oficial del camino.</p></div></section>`}`;
}
async function loadKilometrajeData(projectId=kmProjectId){
 kmProjectId=projectId||'';kmRoads=[];kmSegments=[];kmError='';
 if(!window.geoSupabase){kmError='Supabase no está disponible. Configura la conexión para consultar datos reales.';show();return}
 if(!geoOrg){kmError='No se ha cargado la organización del usuario. Abre Proyectos o vuelve a iniciar sesión.';show();return}
 if(!kmProjectId){show();return}
 kmLoading=true;show();
 try{const [r,s]=await Promise.all([
  window.geoSupabase.from('roads').select('id,organization_id,project_id,code,name,road_type,surface_type,length_m,official_length_m,geometry_length_m,data_source,is_test').eq('organization_id',geoOrg.id).eq('project_id',kmProjectId).order('code'),
  window.geoSupabase.from('segments').select('id,organization_id,project_id,road_id,code,start_km,end_km,condition,geometry_length_m,data_source,is_test').eq('organization_id',geoOrg.id).eq('project_id',kmProjectId).order('start_km')
 ]);if(r.error)throw r.error;if(s.error)throw s.error;kmRoads=r.data||[];kmSegments=s.data||[];
 }catch(e){kmError=projectErrorMessage(e);kmRoads=[];kmSegments=[]}finally{kmLoading=false;if(active==='kilometraje')show()}
}
