 camera.addEventListener('change',()=>{const f=camera.files?.[0];if(f){gallery.value='';setPhoto(f)}});gallery.addEventListener('change',()=>{const f=gallery.files?.[0];if(f){camera.value='';setPhoto(f)}});$('#iPhotoRemove').addEventListener('click',()=>{camera.value='';gallery.value='';setPhoto(null)});window.__geotraciaInspectionPhoto=null;
